import socket
from tornado.testing import AsyncHTTPTestCase
from tornado.web import Application, RequestHandler
from tornado.httpclient import HTTPRequest
from tornado.simple_httpclient import SimpleAsyncHTTPClient
from tornado.netutil import Resolver

class DummyResolver(Resolver):
    def resolve(self, host, port, family=socket.AF_UNSPEC, callback=None):
        callback([(socket.AF_INET, ("127.0.0.1", port))])

class H(RequestHandler):
    def get(self): self.write("ok")
    def post(self): self.write("ok")

class T(AsyncHTTPTestCase):
    def get_app(self):
        return Application([("/", H)])
    def get_http_client(self):
        return SimpleAsyncHTTPClient(io_loop=self.io_loop, force_instance=True,
                                     resolver=DummyResolver())
    def _fetch_req(self, req):
        self.http_client.fetch(req, self.stop)
        return self.wait()
    def test_get_body(self):
        resp = self._fetch_req(HTTPRequest(self.get_url("/"), method="GET", body=b"data"))
        assert isinstance(resp.error, AssertionError), repr(resp.error)
        assert str(resp.error) == "Body must be empty for GET request.", str(resp.error)
    def test_post_no_body(self):
        resp = self._fetch_req(HTTPRequest(self.get_url("/"), method="POST"))
        assert isinstance(resp.error, AssertionError), repr(resp.error)
        assert str(resp.error) == "Body must not be empty for POST request.", str(resp.error)
    def test_post_ok(self):
        resp = self._fetch_req(HTTPRequest(self.get_url("/"), method="POST", body=b"x"))
        assert resp.code == 200, repr(resp.error)
    def test_get_ok(self):
        resp = self._fetch_req(HTTPRequest(self.get_url("/"), method="GET"))
        assert resp.code == 200, repr(resp.error)

import unittest
unittest.main(argv=["x"], verbosity=2)
